"""Parsing of structured log lines.

A line has the shape:

    <timestamp> <LEVEL> key=value key="quoted value" ...

The timestamp is an ISO-8601 string. The level is one of DEBUG, INFO, WARN,
ERROR. Fields are key=value pairs separated by spaces; a value may be wrapped
in double quotes when it contains spaces.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Iterable, Iterator

LEVELS = ("DEBUG", "INFO", "WARN", "ERROR")


class ParseError(ValueError):
    """Raised when a line does not match the expected shape."""


@dataclass(frozen=True)
class LogRecord:
    timestamp: str
    level: str
    fields: dict[str, str] = field(default_factory=dict)


def _split_fields(text: str) -> dict[str, str]:
    fields: dict[str, str] = {}
    for token in text.split(" "):
        if not token:
            continue
        if "=" not in token:
            raise ParseError(f"field without '=': {token!r}")
        key, value = token.split("=", 1)
        if value.startswith('"') and value.endswith('"') and len(value) >= 2:
            value = value[1:-1]
        fields[key] = value
    return fields


def parse_line(line: str) -> LogRecord:
    """Parse one log line into a LogRecord.

    Raises ParseError if the line is malformed.
    """
    stripped = line.strip()
    if not stripped:
        raise ParseError("empty line")
    parts = stripped.split(" ", 2)
    if len(parts) < 2:
        raise ParseError(f"expected '<timestamp> <LEVEL> ...', got {line!r}")
    timestamp, level = parts[0], parts[1]
    if level not in LEVELS:
        raise ParseError(f"unknown level {level!r}")
    rest = parts[2] if len(parts) == 3 else ""
    return LogRecord(timestamp=timestamp, level=level, fields=_split_fields(rest))


def parse_lines(lines: Iterable[str]) -> Iterator[LogRecord]:
    """Parse many lines, skipping blank ones."""
    for line in lines:
        if not line.strip():
            continue
        yield parse_line(line)
